package com.qboix.app;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.*;import android.speech.tts.TextToSpeech;import org.json.*;import java.util.*;
public class GpsTrackingService extends Service implements LocationListener{
 public static final String ACTION="com.qboix.app.GPS_UPDATE",START="START",PAUSE="PAUSE",RESUME="RESUME",FINISH="FINISH",EXTRA_INTERVAL="interval_metres",EXTRA_TRACK_LENGTH="track_length",EXTRA_TRACK_MODE="track_mode";private static final String CHANNEL="qboix_gps_tracking";
 private LocationManager manager;private final ArrayList<Location> points=new ArrayList<>();private final JSONArray lapSplits=new JSONArray();private boolean trackMode;private double trackLength=400,nextLapAt=400;private long lapStarted;private int lapCount;private Location previous;private double metres,intervalMetres=1000,nextAlertAt=1000;private long started,pausedMs,pauseAt,intervalStarted;private boolean active,paused;private TextToSpeech speech;private boolean speechReady;private final Handler handler=new Handler(Looper.getMainLooper());
 private final Runnable ticker=new Runnable(){public void run(){broadcast();if(active&&!paused)handler.postDelayed(this,1000);}};
 public void onCreate(){super.onCreate();manager=(LocationManager)getSystemService(LOCATION_SERVICE);speech=new TextToSpeech(this,s->{speechReady=s==TextToSpeech.SUCCESS;if(speechReady)speech.setLanguage(Locale.getDefault());});if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(CHANNEL,"Q-BOIX GPS tracking",NotificationManager.IMPORTANCE_LOW);getSystemService(NotificationManager.class).createNotificationChannel(c);}}
 public int onStartCommand(Intent i,int flags,int id){String a=i==null?null:i.getAction();if(START.equals(a)){intervalMetres=i.getDoubleExtra(EXTRA_INTERVAL,1000);trackLength=i.getDoubleExtra(EXTRA_TRACK_LENGTH,400);trackMode=i.getBooleanExtra(EXTRA_TRACK_MODE,false);startRun();}else if(PAUSE.equals(a))pauseRun();else if(RESUME.equals(a))resumeRun();else if(FINISH.equals(a))finishRun();return START_STICKY;}
 private Notification notification(String msg){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setContentTitle("Q-BOIX running").setContentText(msg).setSmallIcon(android.R.drawable.ic_menu_mylocation).setOngoing(true).build();}
 private void speak(String msg){if(speechReady&&speech!=null)speech.speak(msg,TextToSpeech.QUEUE_ADD,null,"qboix_"+SystemClock.elapsedRealtime());}
 private void startRun(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return;}try{if(!manager.isProviderEnabled(LocationManager.GPS_PROVIDER)){send("Turn on GPS/location.");stopSelf();return;}points.clear();while(lapSplits.length()>0)lapSplits.remove(0);lapCount=0;previous=null;metres=0;pausedMs=0;started=SystemClock.elapsedRealtime();intervalStarted=started;lapStarted=started;nextAlertAt=intervalMetres;nextLapAt=trackLength;active=true;paused=false;startForeground(7101,notification("Recording your run"));manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this,Looper.getMainLooper());Location l=manager.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(l!=null)onLocationChanged(l);handler.removeCallbacks(ticker);handler.post(ticker);send("GPS recording. Screen may be locked.");speak("Q BOIX run started. Target alert every "+distanceText(intervalMetres)+".");}catch(Exception e){send("Could not start GPS tracking.");stopSelf();}}
 private String distanceText(double m){return m>=1000?String.format(Locale.US,"%.1f kilometres",m/1000):((int)m)+" metres";}
 private void pauseRun(){if(!active||paused)return;paused=true;pauseAt=SystemClock.elapsedRealtime();manager.removeUpdates(this);handler.removeCallbacks(ticker);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7101,notification("Run paused"));broadcast();speak("Run paused.");}
 private void resumeRun(){if(!active||!paused)return;long now=SystemClock.elapsedRealtime();pausedMs+=now-pauseAt;intervalStarted+=now-pauseAt;paused=false;try{manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,this,Looper.getMainLooper());handler.post(ticker);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7101,notification("Recording your run"));broadcast();speak("Run resumed.");}catch(SecurityException e){send("Location permission required.");}}
 private void finishRun(){if(!active){stopForeground(true);stopSelf();return;}active=false;manager.removeUpdates(this);handler.removeCallbacks(ticker);long end=paused?pauseAt:SystemClock.elapsedRealtime();int sec=(int)Math.max(1,(end-started-pausedMs)/1000);double avg=metres>0?sec/(metres/1000):0;JSONArray route=new JSONArray();for(Location p:points){JSONObject o=new JSONObject();try{o.put("lat",p.getLatitude());o.put("lon",p.getLongitude());o.put("accuracy",p.getAccuracy());route.put(o);}catch(Exception ignored){}}WorkoutStore.saveRun(this,metres,sec,avg,route,lapSplits,trackMode,trackLength,lapCount);broadcastWithMessage("Run saved offline.",sec);speak("Run saved. Total distance "+distanceText(metres)+". Total time "+clock(sec)+". Average pace "+paceText(avg)+" per kilometre.");stopForeground(true);stopSelf();}
 private String clock(int s){return String.format(Locale.US,"%d minutes %02d seconds",s/60,s%60);}private String paceText(double p){if(p<=0)return "not available";int s=(int)p;return String.format(Locale.US,"%d minutes %02d seconds",s/60,s%60);}
 public void onLocationChanged(Location l){if(!active||paused||l==null||!l.hasAccuracy()||l.getAccuracy()>35)return;if(previous!=null){float d=previous.distanceTo(l);long sec=Math.max(1,(l.getTime()-previous.getTime())/1000);if(d<1.5)return;if(d/sec>8.5)return;metres+=d;}previous=new Location(l);points.add(new Location(l));if(trackMode&&metres>=nextLapAt){long now=SystemClock.elapsedRealtime();int split=(int)((now-lapStarted)/1000);lapCount++;try{JSONObject lap=new JSONObject();lap.put("lap",lapCount);lap.put("distanceMeters",trackLength);lap.put("splitSeconds",split);lap.put("cumulativeSeconds",(int)((now-started-pausedMs)/1000));lapSplits.put(lap);}catch(JSONException ignored){}speak("Lap "+lapCount+". "+distanceText(trackLength)+". Split time "+clock(split)+".");lapStarted=now;nextLapAt+=trackLength;broadcastLap();}if(metres>=nextAlertAt){long now=SystemClock.elapsedRealtime();int totalSec=(int)((now-started-pausedMs)/1000),lapSec=(int)((now-intervalStarted)/1000);double avg=metres>0?totalSec/(metres/1000):0,lapPace=lapSec/(intervalMetres/1000);speak("Distance "+distanceText(nextAlertAt)+". Total time "+clock(totalSec)+". Last interval "+clock(lapSec)+". Average pace "+paceText(avg)+" per kilometre. Interval pace "+paceText(lapPace)+" per kilometre.");intervalStarted=now;nextAlertAt+=intervalMetres;}broadcast();}
 private void broadcastLap(){Intent i=new Intent(ACTION);i.setPackage(getPackageName());i.putExtra("lap_count",lapCount);i.putExtra("lap_split",lapSplits.optJSONObject(lapSplits.length()-1)==null?0:lapSplits.optJSONObject(lapSplits.length()-1).optInt("splitSeconds",0));i.putExtra("message","Track lap "+lapCount+" completed.");sendBroadcast(i);}
 private void broadcast(){long now=paused?pauseAt:SystemClock.elapsedRealtime();int sec=active?(int)Math.max(0,(now-started-pausedMs)/1000):0;Intent i=new Intent(ACTION);i.setPackage(getPackageName());i.putExtra("distance",metres);i.putExtra("seconds",sec);i.putExtra("pace",metres>=20?sec/(metres/1000):0);i.putExtra("active",active);i.putExtra("paused",paused);i.putExtra("lap_count",lapCount);i.putExtra("message",paused?"Run paused.":"GPS recording • "+points.size()+" route points");sendBroadcast(i);}
 private void broadcastWithMessage(String msg,int sec){Intent i=new Intent(ACTION);i.setPackage(getPackageName());i.putExtra("distance",metres);i.putExtra("seconds",sec);i.putExtra("pace",metres>0?sec/(metres/1000):0);i.putExtra("active",false);i.putExtra("paused",false);i.putExtra("lap_count",lapCount);i.putExtra("message",msg);sendBroadcast(i);}
 private void send(String m){broadcastWithMessage(m,0);}
 public void onDestroy(){manager.removeUpdates(this);handler.removeCallbacks(ticker);if(speech!=null){speech.stop();speech.shutdown();}super.onDestroy();}public IBinder onBind(Intent i){return null;}
}